return $input.all().map(item => {
  const rule = $('When fetching a dataset row').first().json.rule_text;
  const actual = item.json.output;
  const body = {
    model: "gpt-4o-mini",
    temperature: 0,
    messages: [
      {
        role: "system",
        content: "You are a strict grader. Reply with only a JSON object: { \"score\": <0 to 1>, \"reason\": <one sentence> }. No other text."
      },
      {
        role: "user",
        content: `Rule: ${rule}\nActual output: ${actual}`
      }
    ]
  };
  return { json: { requestBody: JSON.stringify(body) } };
});

return $input.all().map(item => {
  try {
    const raw = item.json.choices?.[0]?.message?.content;

    if (!raw) {
      return { json: { error: "No content found in input data" } };
    }

    const cleanRaw = raw.replace(/^```json\s*/i, "").replace(/```\s*$/, "").trim();
    const parsed = JSON.parse(cleanRaw);

    return { 
      json: { 
        score: parsed.score ?? null, 
        reason: parsed.reason ?? "No reason provided" 
      } 
    };
  } catch (error) {
    return { 
      json: { 
        error: "Failed to parse JSON", 
        details: error.message, 
        raw_content: item.json.choices?.[0]?.message?.content 
      } 
    };
  }
});
